&= \{ \Lambda^{\mu} \, _{\rho} \gamma^{\rho} , \Lambda^{\nu} \, _{\sigma} \gamma^{\sigma} \} \\
&= \{ \gamma'^{\mu} , \gamma'^{\mu} \}
